33	// A single parametric environment entry (binds a parametric integral typed
34	// variable name to a value). For example, in:
35	//
36	//    fn id<N: u32>(x: uN[N]) -> uN[N] { x }
37	//    fn main() -> u32 { id(u32:0) }
38	//
39	// The parametric env item for N given id invoked in main is `{"N", 32}`.
40	struct ParametricEnvItem {
41	  std::string identifier;
42	  InterpValue value;
43	
44	  bool operator==(const ParametricEnvItem& other) const {
45	    return identifier == other.identifier && value == other.value;
46	  }
47	  bool operator!=(const ParametricEnvItem& other) const {
48	    return !(*this == other);
49	  }
50	};
51	
52	// Sequence of parametric bindings in stable order (wraps the backing vector
53	// storage to make it immutable, hashable, among other utility functions).
54	//
55	// Stable order is that bindings are sorted as (identifier, value) tuples.
56	class ParametricEnv {
57	 public:
58	  ParametricEnv() = default;
59	
60	  explicit ParametricEnv(
61	      absl::Span<std::pair<std::string, InterpValue> const> items) {
62	    for (const auto& item : items) {
63	      bindings_.push_back(ParametricEnvItem{item.first, item.second});
64	    }
65	    Sort();
66	  }
67	  explicit ParametricEnv(
68	      const absl::flat_hash_map<std::string, InterpValue>& mapping) {
69	    for (const auto& item : mapping) {
70	      bindings_.push_back(ParametricEnvItem{item.first, item.second});
71	    }
72	    Sort();
73	  }
74	
75	  template <typename H>
76	  friend H AbslHashValue(H h, const ParametricEnv& self) {
77	    for (const ParametricEnvItem& sb : self.bindings_) {
78	      h = H::combine(std::move(h), sb.identifier, sb.value.ToString());
79	    }
80	    return h;
81	  }
82	
83	  bool operator==(const ParametricEnv& other) const;
84	  bool operator!=(const ParametricEnv& other) const;
85	
86	  bool empty() const { return bindings_.empty(); }
87	
88	  // Returns a string representation of the contained parametric bindings
89	  // suitable for debugging.
90	  std::string ToString() const;
91	
92	  // Returns a map representation of these parametric bindings.
93	  absl::flat_hash_map<std::string, InterpValue> ToMap() const;
94	
95	  // Returns the set of keys in these parametric bindings. A btree is given for
96	  // ease of range-based comparisons.
97	  absl::btree_set<std::string> GetKeySet() const;
98	
99	  int64_t size() const { return bindings_.size(); }
100	  const std::vector<ParametricEnvItem>& bindings() const { return bindings_; }
101	
102	  // Returns the value of the given binding, if any is mapped in this env.
103	  std::optional<InterpValue> GetValue(const NameDef* binding) const;
104	
105	 private:
106	  // Sorts all of the bindings_ elements (to maintain the sorted-order invariant
107	  // of this data structure).
108	  void Sort();
109	
110	  std::vector<ParametricEnvItem> bindings_;
111	};
112	
113	inline std::ostream& operator<<(std::ostream& os,
114	                                const ParametricEnv& parametric_env) {
115	  os << parametric_env.ToString();
116	  return os;
117	}
118	
119	}  // namespace xls::dslx
