58	// Represents a parametric binding in a Type, which is either a) a
59	// parametric expression or b) evaluated to an InterpValue. When type
60	// annotations from the AST are evaluated in type inference, some of the
61	// "concrete types" that result from deduction may still be parametric. When the
62	// parametric code is instantiated, the concrete types then have concrete
63	// `InterpValues` as their dimensions.
64	//
65	// See comment on `Type` below for more details.
66	class TypeDim {
67	 public:
68	  // Evaluates the given value to a 64-bit quantity.
69	  static absl::StatusOr<int64_t> GetAs64Bits(const InterpValue& value);
70	
71	  // Creates a u32 `InterpValue`-based TypeDim with the given "value".
72	  static TypeDim CreateU32(uint32_t value) {
73	    return TypeDim(InterpValue::MakeU32(value));
74	  }
75	
76	  // Creates a `u1` / `bool` `InterpValue`-based TypeDim with the given "value".
77	  static TypeDim CreateBool(bool value) {
78	    return TypeDim(InterpValue::MakeBool(value));
79	  }
80	
81	  explicit TypeDim(InterpValue value);
82	
83	  TypeDim(const TypeDim& other);
84	  TypeDim(TypeDim&& other) = default;
85	  TypeDim& operator=(TypeDim&& other) = default;
86	
87	  TypeDim Clone() const;
88	
89	  // Arithmetic operators used in e.g. calculating total bit counts.
90	  absl::StatusOr<TypeDim> Mul(const TypeDim& rhs) const;
91	  absl::StatusOr<TypeDim> Add(const TypeDim& rhs) const;
92	  absl::StatusOr<TypeDim> CeilOfLog2() const;
93	
94	  // Returns a string representation of this dimension, which is either the
95	  // integral string or the parametric expression string conversion.
96	  std::string ToString() const;
97	
98	  // Returns a string representation of this dimension with more internal
99	  // details, suitable for debugging.
100	  std::string ToDebugString() const;
101	
102	  bool operator==(const TypeDim& other) const;
103	  bool operator==(const InterpValue& other) const;
104	  bool operator!=(const TypeDim& other) const { return !(*this == other); }
105	
106	  const InterpValue& value() const { return value_; }
107	
108	  // Retrieves the bit value of the underlying InterpValue as an int64_t.
109	  absl::StatusOr<int64_t> GetAsInt64() const;
110	
111	  // Retrieves the bit value of the underlying InterpValue as a bool.
112	  absl::StatusOr<bool> GetAsBool() const;
113	
114	 private:
115	  InterpValue value_;
116	};
