197	// Indicates whether we should fully qualify types when converting them to
198	// string -- this is useful when types are nominally the same but come from
199	// different modules (e.g. MyStruct defined in both `a.x` and `b.x`).
200	enum FullyQualify {
201	  kNo,
202	  kYes,
203	};
204	
205	// Represents a 'concrete' (evaluated) type, as determined by evaluating a
206	// TypeAnnotation in the AST.
207	//
208	// Type constructs in the AST may have abstract expressions, but ultimately they
209	// resolve into some concrete type when those are evaluated. By IR conversion
210	// time all the dimensions are fully resolvable to integers. This class
211	// represents both the parametric forms (before final resolution) and the
212	// resolved result.
213	//
214	// Note: During typechecking the dimension members may be either symbols (like
215	// the 'N' in `bits[N][3]`) or integers. Once parametric symbols are
216	// instantiated the symbols (such as 'N') will have resolved into ints, and we
217	// will only be dealing with TypeDims that hold ints.
218	class Type {
219	 public:
220	  using MapFn = std::function<absl::StatusOr<TypeDim>(TypeDim)>;
221	
222	  // Creates a "unit" tuple type (a tuple type with no members).
223	  static std::unique_ptr<Type> MakeUnit();
224	
225	  // Creates a concrete type matching that of the given InterpValue.
226	  static absl::StatusOr<std::unique_ptr<Type>> FromInterpValue(
227	      const InterpValue& value);
228	
229	  virtual ~Type();
230	
231	  virtual absl::Status Accept(TypeVisitor& v) const = 0;
232	
233	  // Note that this is type equivalence; e.g. types are equivalent and
234	  // substitutable if this equality holds.
235	  virtual bool operator==(const Type& other) const = 0;
236	  bool operator!=(const Type& other) const { return !(*this == other); }
237	
238	  // Returns a string representation of this type.
239	  std::string ToString() const {
240	    return ToStringInternal(FullyQualify::kNo, /*file_table=*/nullptr);
241	  }
242	
243	  // Returns a string representation of this type, but for nominal type
244	  // entities, like structs and enums, prefixes the struct/enum name with the
245	  // module in which it is defined.
246	  //
247	  // This can help disambiguate cases where the same struct name is used in
248	  // different modules and they are not compatible with each other, we need to
249	  // report a non-confusing error by qualifying which struct/enum we're
250	  // referring to more precisely.
251	  std::string ToStringFullyQualified(const FileTable& file_table) const {
252	    return ToStringInternal(FullyQualify::kYes, &file_table);
253	  }
254	
255	  // Converts the type to a string with given `fully_qualify` mode request.
256	  //
257	  // Note: if the FullyQualify request is kNo, we should not need the
258	  // file_table, and so it can be null in that case.
259	  virtual std::string ToStringInternal(FullyQualify fully_qualify,
260	                                       const FileTable* file_table) const = 0;
261	
262	  // Variation on `ToString()` to be used in user-facing error reporting.
263	  virtual std::string ToErrorString() const { return ToString(); }
264	
265	  // Returns an "inlay hint" representation of this type that will be shown
266	  // e.g. in a code editor when a type is inferred.
267	  //
268	  // For example, for structs, this does not show the internal structure, just
269	  // the nominal part (the struct name).
270	  //
271	  // e.g. consider:
272	  //
273	  // ```dslx-snippet
274	  // fn f(s: MyStruct) -> MyStruct {
275	  //   let s = MyStruct{foo: u32:42, ..s};
276	  //        ^~~~~ inlay hint goes here as ": MyStruct"
277	  //   s
278	  // }
279	  // ```
280	  virtual std::string ToInlayHintString() const { return ToString(); }
281	
282	  // Returns whether this type contains an enum type (transitively).
283	  virtual bool HasEnum() const = 0;
284	
285	  // Returns whether this type contains a token type (transitively).
286	  virtual bool HasToken() const = 0;
287	
288	  // Returns whether this type is (or contains) an aggregate.
289	  //
290	  // Generally any type that contains other types is considered an aggregate.
291	  //
292	  // We do notably make an exception for the nil tuple as it's often used as a
293	  // "void style" type.
294	  virtual bool IsAggregate() const = 0;
295	
296	  // Returns a flat sequence of all dimensions contained (transitively) within
297	  // this type.
298	  virtual std::vector<TypeDim> GetAllDims() const = 0;
299	
300	  virtual absl::StatusOr<TypeDim> GetTotalBitCount() const = 0;
301	
302	  // Returns a "type name" suitable for debugging; e.g. "array", "bits", "enum",
303	  // etc.
304	  virtual std::string GetDebugTypeName() const = 0;
305	
306	  // Creates a new unique clone of this Type.
307	  //
308	  // Postcondition: *retval == *this.
309	  virtual std::unique_ptr<Type> CloneToUnique() const = 0;
310	
311	  // Type equality, but ignores tuple member naming discrepancies.
312	  bool CompatibleWith(const Type& other) const;
313	
314	  bool IsChannel() const;
315	  bool IsUnit() const;
316	  bool IsToken() const;
317	  bool IsStruct() const;
318	  bool IsProc() const;
319	  bool IsEnum() const;
320	  bool IsArray() const;
321	  bool IsMeta() const;
322	  bool IsTuple() const;
323	  bool IsFunction() const;
324	  bool IsModule() const;
325	
326	  const ChannelType& AsChannel() const;
327	  const StructType& AsStruct() const;
328	  const ProcType& AsProc() const;
329	  const EnumType& AsEnum() const;
330	  const ArrayType& AsArray() const;
331	  const FunctionType& AsFunction() const;
332	  const MetaType& AsMeta() const;
333	  const TupleType& AsTuple() const;
334	
335	  virtual std::optional<const ChannelType*> GetDirectOrElementChannelType()
336	      const {
337	    return std::nullopt;
338	  }
339	
340	 protected:
341	  static std::vector<std::unique_ptr<Type>> CloneSpan(
342	      absl::Span<const std::unique_ptr<Type>> ts);
343	
344	  static bool Equal(absl::Span<const std::unique_ptr<Type>> a,
345	                    absl::Span<const std::unique_ptr<Type>> b);
346	};
347	
348	inline std::ostream& operator<<(std::ostream& os, const Type& t) {
349	  os << t.ToString();
350	  return os;
351	}
352	
353	// Indicates that the deduced entity is a type expression -- as opposed to "an
354	// expression having type T" this indicates "it was type T itself".
355	//
356	// For example, if you do `deduce(u32)` where `u32` is the builtin type
357	// annotation, it will tell you "this thing is a type" and contain "the type is
358	// u32".
359	class MetaType : public Type {
360	 public:
361	  explicit MetaType(std::unique_ptr<Type> wrapped)
362	      : wrapped_(std::move(wrapped)) {}
363	
364	  ~MetaType() override;
365	
366	  absl::Status Accept(TypeVisitor& v) const override {
367	    return v.HandleMeta(*this);
368	  }
369	  bool operator==(const Type& other) const override {
370	    if (const auto* o = dynamic_cast<const MetaType*>(&other)) {
371	      return *wrapped() == *o->wrapped();
372	    }
373	    return false;
374	  }
375	  std::string GetDebugTypeName() const override { return "meta-type"; }
376	
377	  bool HasEnum() const override { return wrapped_->HasEnum(); }
378	  bool HasToken() const override { return wrapped_->HasToken(); }
379	  bool IsAggregate() const override { return wrapped_->IsAggregate(); }
380	  std::vector<TypeDim> GetAllDims() const override {
381	    return wrapped_->GetAllDims();
382	  }
383	  absl::StatusOr<TypeDim> GetTotalBitCount() const override;
384	
385	  std::unique_ptr<Type> CloneToUnique() const override {
386	    return std::make_unique<MetaType>(wrapped_->CloneToUnique());
387	  }
388	
389	  const std::unique_ptr<Type>& wrapped() const { return wrapped_; }
390	  std::unique_ptr<Type>& wrapped() { return wrapped_; }
391	
392	  std::string ToStringInternal(FullyQualify fully_qualify,
393	                               const FileTable* file_table) const override {
394	    return absl::StrCat(
395	        "typeof(", wrapped_->ToStringInternal(fully_qualify, file_table), ")");
396	  }
397	
398	 private:
399	  std::unique_ptr<Type> wrapped_;
400	};
401	
402	// Represents the type of a token value.
403	//
404	// Tokens are *existential values* used for establishing dataflow dependencies
405	// for sequence-sensitive operations.
