903	// Represents a function type with params and a return type.
904	class FunctionType : public Type {
905	 public:
906	  static std::string GetDebugName() { return "FunctionType"; }
907	
908	  FunctionType(std::vector<std::unique_ptr<Type>> params,
909	               std::unique_ptr<Type> return_type)
910	      : params_(std::move(params)), return_type_(std::move(return_type)) {
911	    CHECK(!return_type_->IsMeta());
912	  }
913	
914	  absl::Status Accept(TypeVisitor& v) const override {
915	    return v.HandleFunction(*this);
916	  }
917	  std::string ToStringInternal(FullyQualify fully_qualify,
918	                               const FileTable* file_table) const override;
919	  std::string GetDebugTypeName() const override { return "function"; }
920	  std::vector<TypeDim> GetAllDims() const override;
921	  absl::StatusOr<TypeDim> GetTotalBitCount() const override;
922	
923	  bool operator==(const Type& other) const override;
924	
925	  // Accessor for owned parameter (formal argument) type vector.
926	  const std::vector<std::unique_ptr<Type>>& params() const { return params_; }
927	
928	  // Returns a (new value) vector of pointers to parameter types owned by this
929	  // FunctionType.
930	  std::vector<const Type*> GetParams() const;
931	
932	  // Number of parameters (formal arguments) to this function.
933	  int64_t GetParamCount() const { return params_.size(); }
934	
935	  bool HasEnum() const override {
936	    auto has_enum = [](const auto& param) { return param->HasEnum(); };
937	    return absl::c_any_of(params_, has_enum) || return_type_->HasEnum();
938	  }
939	  bool HasToken() const override {
940	    auto has_token = [](const auto& param) { return param->HasToken(); };
941	    return absl::c_any_of(params_, has_token) || return_type_->HasToken();
942	  }
943	  bool IsAggregate() const override { return true; }
944	
945	  // Return type of the function.
946	  const Type& return_type() const { return *return_type_; }
947	
948	  std::unique_ptr<Type> CloneToUnique() const override {
949	    std::vector<std::unique_ptr<Type>> params;
950	    params.reserve(params_.size());
951	    for (const auto& item : params_) {
952	      params.push_back(item->CloneToUnique());
953	    }
954	    return std::make_unique<FunctionType>(std::move(params),
955	                                          return_type_->CloneToUnique());
956	  }
957	
958	 private:
959	  std::vector<std::unique_ptr<Type>> params_;
960	  std::unique_ptr<Type> return_type_;
961	};
