1000	// Helper for the case where we have a derived (i.e. non-abstract) Type,
1001	// and want the clone to also be a unique_ptr of the derived type.
1002	//
1003	// Note: we explicitly instantiate it so we get better type error messages than
1004	// exposing the parametric version directly to callers.
1005	template <typename T>
1006	inline std::unique_ptr<T> CloneToUniqueInternal(const T& type) {
1007	  static_assert(std::is_base_of_v<Type, T>);
1008	  std::unique_ptr<Type> cloned = type.CloneToUnique();
1009	  return absl::WrapUnique<T>(dynamic_cast<T*>(cloned.release()));
1010	}
1011	inline std::unique_ptr<BitsType> CloneToUnique(const BitsType& type) {
1012	  return CloneToUniqueInternal(type);
1013	}
1014	inline std::unique_ptr<TupleType> CloneToUnique(const TupleType& type) {
1015	  return CloneToUniqueInternal(type);
1016	}
1017	inline std::unique_ptr<StructType> CloneToUnique(const StructType& type) {
1018	  return CloneToUniqueInternal(type);
1019	}
1020	inline std::unique_ptr<FunctionType> CloneToUnique(const FunctionType& type) {
1021	  return CloneToUniqueInternal(type);
1022	}
1023	
1024	// As above, but works on a vector of Type unique pointers.
1025	inline std::vector<std::unique_ptr<Type>> CloneToUnique(
1026	    absl::Span<const std::unique_ptr<Type>> types) {
1027	  std::vector<std::unique_ptr<Type>> result;
1028	  for (const auto& item : types) {
1029	    result.push_back(item->CloneToUnique());
1030	  }
1031	  return result;
1032	}
1033	
1034	// As above, but works on a vector of Type unique pointers.
1035	inline std::vector<std::unique_ptr<Type>> CloneToUnique(
1036	    absl::Span<const Type* const> types) {
1037	  std::vector<std::unique_ptr<Type>> result;
1038	  for (const auto* item : types) {
1039	    result.push_back(item->CloneToUnique());
1040	  }
1041	  return result;
1042	}
1043	
1044	inline bool IsBitsConstructor(const Type& t) {
1045	  return dynamic_cast<const BitsConstructorType*>(&t) != nullptr;
1046	}
1047	
1048	// Returns whether `t` is an array that wraps a `BitsConstructorType` as its
1049	// element type -- this indicates it is a value with signedness (from the
1050	// element type) as well as size (from the array dimension).
1051	inline bool IsArrayOfBitsConstructor(
1052	    const Type& t, const BitsConstructorType** elem_type_out = nullptr) {
1053	  if (auto* a = dynamic_cast<const ArrayType*>(&t)) {
1054	    if (auto* bc =
1055	            dynamic_cast<const BitsConstructorType*>(&a->element_type())) {
1056	      if (elem_type_out != nullptr) {
1057	        *elem_type_out = bc;
1058	      }
1059	      return true;
1060	    }
1061	  }
1062	  return false;
1063	}
1064	
1065	// This predicate should be used when we want to know if a type is effectively a
1066	// bits type -- this includes either the bits type itself or a sized array of
1067	// bits-constructor type.
1068	bool IsBitsLike(const Type& t);
1069	
1070	struct BitsLikeProperties {
1071	  TypeDim is_signed;
1072	  TypeDim size;
1073	};
1074	
1075	// Returns true iff both the signedness and size of the `properties` are known
1076	// constants and they indicate that the type is a `u1` AKA `bool`.
1077	bool IsKnownU1(const BitsLikeProperties& properties);
1078	
1079	// Returns true iff both the signedness and size of the `properties` are known
1080	// constants and they indicate that the type is a `u32`.
1081	bool IsKnownU32(const BitsLikeProperties& properties);
1082	
1083	// Returns a string representation of the BitsLikeProperties that looks similar
1084	// to a corresponding BitsType.
1085	std::string ToTypeString(const BitsLikeProperties& properties);
1086	
1087	inline BitsLikeProperties Clone(const BitsLikeProperties& properties) {
1088	  return BitsLikeProperties{.is_signed = properties.is_signed.Clone(),
1089	                            .size = properties.size.Clone()};
1090	}
1091	
1092	inline bool operator==(const BitsLikeProperties& a,
1093	                       const BitsLikeProperties& b) {
1094	  return a.is_signed == b.is_signed && a.size == b.size;
1095	}
1096	
1097	inline std::ostream& operator<<(std::ostream& os,
1098	                                const BitsLikeProperties& properties) {
1099	  return os << absl::StreamFormat("BitsLikeProperties{is_signed: %s, size: %s}",
1100	                                  properties.is_signed.ToString(),
1101	                                  properties.size.ToString());
1102	}
1103	
1104	// Returns ths "bits-like properties" for a given type `t` -- in practice this
1105	// means that the type can either be a true `BitsType` or an instantiated
1106	// `BitsConstructorType` -- from both of these forms we can retrieve information
1107	// on the signedness and bit count.
1108	//
1109	// They are generally type compatible, so testing via this routine should always
1110	// be preferred to dynamic casting.
1111	std::optional<BitsLikeProperties> GetBitsLike(const Type& t);
1112	
1113	inline bool IsBitsLikeWithNBitsAndSignedness(const Type& t, bool is_signed,
1114	                                             int64_t size) {
1115	  const TypeDim want = TypeDim::CreateU32(size);
1116	  if (auto* b = dynamic_cast<const BitsType*>(&t)) {
1117	    return b->is_signed() == is_signed && b->size() == want;
1118	  }
1119	
1120	  const BitsConstructorType* bc;
1121	  if (IsArrayOfBitsConstructor(t, &bc)) {
1122	    return bc->is_signed() == want &&
1123	           absl::down_cast<const ArrayType&>(t).size() == want;
1124	  }
1125	
1126	  return false;
1127	}
1128	
1129	inline bool IsU8Array(const Type& t) {
1130	  if (auto* array_type = dynamic_cast<const ArrayType*>(&t);
1131	      array_type != nullptr &&
1132	      IsBitsLikeWithNBitsAndSignedness(array_type->element_type(), false, 8)) {
1133	    return true;
1134	  }
1135	  return false;
1136	}
1137	
1138	// Returns whether the given type is a bool (u1).
1139	inline bool IsBool(const Type& t) {
1140	  if (std::optional<BitsLikeProperties> p = GetBitsLike(t)) {
1141	    return IsKnownU1(*p);
1142	  }
1143	  return false;
1144	}
1145	
1146	// Returns whether the given type, which should be either a bits or an enum
1147	// type, is signed.
1148	absl::StatusOr<bool> IsSigned(const Type& c);
1149	
1150	}  // namespace xls::dslx
1151	
1152	#endif  // XLS_DSLX_TYPE_SYSTEM_TYPE_H_
