178	                                std::string_view name,
179	                                TypeInfo* parent = nullptr);
180	
181	  // Retrieves the root type information, or a not-found status error if it is
182	  // not present.
183	  absl::StatusOr<TypeInfo*> GetRootTypeInfo();
184	
185	 private:
186	  // The single root (parentmost) type info across all modules.
187	  TypeInfo* root_type_info_ = nullptr;
188	
189	  // Owned type information objects -- TypeInfoOwner is the lifetime owner for
190	  // these.
191	  std::vector<std::unique_ptr<TypeInfo>> type_infos_;
192	};
