628	template <typename T>
629	inline absl::StatusOr<T*> TypeInfo::GetItemAs(const AstNode* key) const {
630	  static_assert(std::is_base_of<Type, T>::value,
631	                "T must be a subclass of Type");
632	
633	  std::optional<Type*> t = GetItem(key);
634	  if (!t.has_value()) {
635	    return absl::NotFoundError(absl::StrFormat(
636	        "No type found for AST node: %s @ %s in TI %s", key->ToString(),
637	        SpanToString(key->GetSpan(), file_table()), name()));
638	  }
639	  DCHECK(t.value() != nullptr);
640	  auto* target = dynamic_cast<T*>(t.value());
641	  XLS_RET_CHECK(target != nullptr) << absl::StreamFormat(
642	      "AST node `%s` @ %s did not have expected `xls::dslx::Type` subtype; "
643	      "want: %s got: %s",
644	      key->ToString(), SpanToString(key->GetSpan(), file_table()),
645	      T::GetDebugName(), t.value()->GetDebugTypeName());
646	  return target;
647	}
648	
649	}  // namespace xls::dslx
650	
651	#endif  // XLS_DSLX_TYPE_SYSTEM_TYPE_INFO_H_
652

